12	// D27. scan.trivy_path and scan.gitleaks_path were declared in the schema,
13	// defaulted, and tilde-expanded on load — and read by nothing. Detection called
14	// exec.LookPath("trivy") and the command builders hard-coded the name, so
15	// pointing DevDesk at a tool outside PATH did nothing, silently.
16	//
17	// The other half: detection tried the binary first and only reached for Docker
18	// in the else, so a binary on PATH always won. Asking for the pinned image
19	// while trivy happened to be installed was not expressible.
20	
21	// installToolAt writes a fake tool at an explicit path outside PATH, which is
22	// the situation trivy_path exists for.
23	func installToolAt(t *testing.T, dir, name string) string {
24		t.Helper()
25		self, err := os.Executable()
26		if err != nil {
27			t.Fatalf("locating the test binary: %v", err)
28		}
29		body, err := os.ReadFile(self)
30		if err != nil {
31			t.Fatalf("reading the test binary: %v", err)
32		}
33		if runtime.GOOS == "windows" {
34			name += ".exe"
35		}
36		path := filepath.Join(dir, name)
37		if err := os.WriteFile(path, body, 0o755); err != nil {
38			t.Fatalf("installing %s: %v", path, err)
39		}
40		return path
41	}
